"""P2 — Cartographie des Flux Commerciaux"""import streamlit as stimport plotly.graph_objects as gofrom config import C, apply_theme, HEATMAP_SCALEfrom components.kpi_cards import section_title, page_headerfrom data.loader import load_raw, load_flux_top20from data.processor import compute_flux_heatmapdef render():    page_header("Cartographie des Flux",                "Top flux acheteur → vendeur · heatmap & classement · filtres interactifs", "🗺️")    df_raw = load_raw()    df_top = load_flux_top20()    with st.sidebar:        st.markdown(f"<div style='color:{C['muted']};font-size:12px;margin-top:16px;'>FILTRES — FLUX</div>",                    unsafe_allow_html=True)        n_flux  = st.slider("Top N flux à afficher", 5, 20, 15, key="flux_n")        min_tx  = st.slider("Transactions min.", 100, 2000, 500, step=100, key="flux_min")    section_title("Heatmap Acheteur × Vendeur", "🔥")    matrix = compute_flux_heatmap(df_raw)    fig_heat = go.Figure(go.Heatmap(        z=matrix.values,        x=matrix.columns.tolist(),        y=matrix.index.tolist(),        colorscale=HEATMAP_SCALE,        text=matrix.values.astype(int),        texttemplate="%{text}",        textfont=dict(size=10, color=C["text"]),        hovertemplate="<b>%{y}</b> → <b>%{x}</b><br>%{z} transactions<extra></extra>",        colorbar=dict(title="Nb tx", titlefont=dict(color=C["muted"]),                      tickfont=dict(color=C["muted"])),    ))    apply_theme(fig_heat, "Volume de transactions (échantillon — proportions représentatives)")    fig_heat.update_layout(height=480)    fig_heat.update_xaxes(tickangle=-35)    st.plotly_chart(fig_heat, use_container_width=True)    st.markdown(        f'<p style="font-size:11px;color:{C["muted"]};margin-top:-8px;">'        '⚠️ Heatmap calculée sur l\'échantillon de 5 000 transactions.</p>',        unsafe_allow_html=True)    section_title(f"Top {n_flux} flux internationaux classés", "📊")    df_f = df_top[df_top["Nb Transactions"] >= min_tx].head(n_flux).copy()    df_f = df_f.sort_values("Nb Transactions", ascending=True)    fig_bar = go.Figure(go.Bar(        y=df_f["Flux"], x=df_f["Nb Transactions"], orientation="h",        marker=dict(            color=df_f["Note Globale"],            colorscale="RdYlGn", cmin=4.75, cmax=4.87,            colorbar=dict(title=dict(text="Note sat.", font=dict(color=C["muted"])),                          tickfont=dict(color=C["muted"]), x=1.01),            line=dict(color=C["bg"], width=0.5)),        text=[f"  {int(v):,} tx · {n:.3f}⭐"              for v, n in zip(df_f["Nb Transactions"], df_f["Note Globale"])],        textposition="outside", textfont=dict(color=C["text"], size=11),        hovertemplate="<b>%{y}</b><br>%{x:,} transactions<br>%{marker.color:.3f}/5<extra></extra>",    ))    apply_theme(fig_bar, f"Top {n_flux} flux · couleur = note satisfaction")    fig_bar.update_layout(height=max(350, len(df_f)*34+60),                          margin=dict(l=10, r=120, t=55, b=20))    fig_bar.update_xaxes(title_text="Nombre de transactions")    st.plotly_chart(fig_bar, use_container_width=True)    section_title("Données détaillées", "📋")    df_display = df_top[["#","Flux","Nb Transactions","Note Globale",                          "Score Livraison","Score Communication","Part (%)"]].head(n_flux)    st.dataframe(        df_display.style        .background_gradient(subset=["Note Globale"], cmap="RdYlGn", vmin=4.75, vmax=4.87)        .background_gradient(subset=["Nb Transactions"], cmap="Blues")        .format({"Nb Transactions":"{:,.0f}","Note Globale":"{:.3f}",                 "Score Livraison":"{:.3f}","Score Communication":"{:.3f}",                 "Part (%)":"{:.1f}%"}),        use_container_width=True, height=min(400, len(df_display)*37+40))